  "Eukrasian Prognosis": { job: "sage", level: 30, recast: "", range: "0y/20y", url: "https://na.finalfantasyxiv.com/jobguide/sage/", text: "Restores own HP and the HP of all nearby party members. | Cure Potency: 100 | Additional Effect: Erects a magicked barrier which nullifies damage equaling 320% of the amount of HP restored | Duration: 30s | Effect cannot be stacked with those of Eukrasian Diagnosis or scholar's Galvanize. | Can only be executed while under the effect of Eukrasia. | | ※This action cannot be assigned to a hotbar. | ※Prognosis changes to Eukrasian Prognosis when requirements for execution are met." },
  "Kerachole": { job: "sage", level: 50, recast: "30s", range: "0y/30y", url: "https://na.finalfantasyxiv.com/jobguide/sage/", text: "Reduces damage taken by self and nearby party members by 10%. | Duration: 15s | Effect cannot be stacked with Taurochole. | Additional Effect: Regen | Cure Potency: 100 | Duration: 15s | Additional Effect: Restores 7% of maximum MP | Addersgall Cost: 1" },
  "Zoe": { job: "sage", level: 56, recast: "90s", range: "0y/0y", url: "https://na.finalfantasyxiv.com/jobguide/sage/", text: "Increases healing magic potency of your next healing spell by 50%. | Duration: 30s" },
  "Pepsis": { job: "sage", level: 58, recast: "30s", range: "0y/20y", url: "https://na.finalfantasyxiv.com/jobguide/sage/", text: "Restores own HP and the HP of nearby party members by removing Eukrasian Diagnosis and Eukrasian Prognosis effects granted by you. | Eukrasian Diagnosis Cure Potency: 450 | Eukrasian Prognosis Cure Potency: 350 | Targets not under the effect of Eukrasian Diagnosis or Eukrasian Prognosis will not be healed." },
  "Physis II": { job: "sage", level: 60, recast: "60s", range: "0y/30y", url: "https://na.finalfantasyxiv.com/jobguide/sage/", text: "Gradually restores own HP and the HP of all nearby party members. | Cure Potency: 130 | Duration: 15s | Additional Effect: Increases HP recovered by healing actions by 10% | Duration: 15s" },
